import sys
from collections.abc import Sequence

from bubble_sort.core import bubble_sort

DEMO_VALUES = (64, 34, 25, 12, 22, 11, 90)


def parse_values(arguments: Sequence[str]) -> list[int] | list[str]:
    if not arguments:
        return list(DEMO_VALUES)

    try:
        return [int(argument) for argument in arguments]
    except ValueError:
        return list(arguments)


def sorted_values(arguments: Sequence[str]) -> list[int] | list[str]:
    values = parse_values(arguments)
    bubble_sort(values)
    return values


def main(argv: Sequence[str] | None = None) -> None:
    arguments = sys.argv[1:] if argv is None else argv
    values = sorted_values(arguments)
    print(values)

from collections.abc import MutableSequence
from typing import Any, Protocol, TypeVar


class SupportsGreaterThan(Protocol):
    def __gt__(self, other: Any) -> bool:
        ...


Sortable = TypeVar("Sortable", bound=SupportsGreaterThan)


def bubble_sort(values: MutableSequence[Sortable]) -> None:
    """Sort values in ascending order in place using bubble sort."""
    unsorted_limit = len(values) - 1

    while unsorted_limit > 0:
        swapped = False

        for index in range(unsorted_limit):
            if values[index] > values[index + 1]:
                values[index], values[index + 1] = values[index + 1], values[index]
                swapped = True

        if not swapped:
            break

        unsorted_limit -= 1


def bubbleSort(values: MutableSequence[Sortable]) -> None:
    """Compatibility wrapper for callers using the original camelCase name."""
    bubble_sort(values)
